function viewClientes(){
  const rows=active('clientes').sort((a,b)=>(a.nomeRazao||'').localeCompare(b.nomeRazao||''));
  return `<div class="card"><div class="row" style="align-items:center"><div><h2>Clientes</h2><p class="hint">Cadastro manual ou originado do pré-cadastro público. Alterações importantes preservam histórico.</p></div><div class="inline-actions" style="justify-content:flex-end"><button class="btn ghost" onclick="downloadModeloCSV('clientes')">Modelo CSV</button><label class="btn ghost" style="display:inline-grid;place-items:center;margin:0">Importar CSV<input type="file" accept=".csv" hidden onchange="importarCSV(event,'clientes')"></label><button class="btn" onclick="editarCliente()">+ Novo cliente</button></div></div><input class="search" id="cliSearch" placeholder="Pesquisar cliente, CPF/CNPJ, telefone..." oninput="filterTable('cliTable',this.value)">
  ${rows.length?`<table id="cliTable"><thead><tr><th>Cliente</th><th>Documento</th><th>Responsável</th><th>Contato</th><th>Segmento</th><th>Ações</th></tr></thead><tbody>${rows.map(c=>`<tr data-search="${esc([c.nomeRazao,c.cpfCnpj,c.responsavel,c.telefone,c.email,c.segmento].join(' '))}"><td><b>${esc(c.nomeRazao)}</b><br><span class="muted">${esc(c.tipoPessoa||'')}</span></td><td>${esc(c.cpfCnpj||'—')}</td><td>${esc(c.responsavel||'—')}</td><td>${esc(c.telefone||'—')}<br><span class="muted">${esc(c.email||'')}</span></td><td>${esc(c.segmento||'—')}</td><td><div class="inline-actions"><button class="btn small ghost" onclick="detalharCliente('${c.id}')">Abrir</button><button class="btn small ghost" onclick="editarCliente('${c.id}')">Editar</button></div></td></tr>`).join('')}</tbody></table>`:empty('Nenhum cliente cadastrado.')}</div>`;
}
function clienteForm(c={}){return `<div class="grid2"><div><label>Tipo</label><select id="cTipo"><option ${c.tipoPessoa==='PF'?'selected':''}>PF</option><option ${c.tipoPessoa==='PJ'?'selected':''}>PJ</option></select></div><div><label>Nome / Razão Social *</label><input id="cNome" value="${esc(c.nomeRazao||'')}"></div><div><label>CPF / CNPJ *</label><input id="cCpf" value="${esc(c.cpfCnpj||'')}"></div><div><label>Responsável</label><input id="cResp" value="${esc(c.responsavel||'')}"></div><div><label>CPF do responsável</label><input id="cCpfResp" value="${esc(c.cpfResponsavel||'')}"></div><div><label>Segmento</label><input id="cSegmento" value="${esc(c.segmento||'')}"></div><div><label>Telefone</label><input id="cTel" value="${esc(c.telefone||'')}"></div><div><label>Telefone de referência</label><input id="cTelRef" value="${esc(c.telefoneReferencia||'')}"></div><div><label>E-mail</label><input id="cEmail" type="email" value="${esc(c.email||'')}"></div><div><label>Origem do contato</label><input id="cOrigem" value="${esc(c.origem||'')}"></div></div><div class="section-title">Endereço cadastral / residencial</div>${addressForm('cEnd',c.enderecoCadastral||{})}<div class="section-title">Endereço de instalação principal</div>${addressForm('cInst',(c.enderecosInstalacao||[])[0]||{})}`}
function addressForm(p,a={}){return `<div class="grid3"><div><label>Logradouro</label><input id="${p}Log" value="${esc(a.logradouro||'')}"></div><div><label>Número</label><input id="${p}Num" value="${esc(a.numero||'')}"></div><div><label>Complemento</label><input id="${p}Comp" value="${esc(a.complemento||'')}"></div><div><label>Bairro</label><input id="${p}Bairro" value="${esc(a.bairro||'')}"></div><div><label>Cidade</label><input id="${p}Cidade" value="${esc(a.cidade||'')}"></div><div><label>UF</label><input id="${p}Uf" value="${esc(a.uf||'')}"></div><div><label>CEP</label><input id="${p}Cep" value="${esc(a.cep||'')}"></div></div>`}
function modalAddress(p){return {logradouro:$(`${p}Log`).value.trim(),numero:$(`${p}Num`).value.trim(),complemento:$(`${p}Comp`).value.trim(),bairro:$(`${p}Bairro`).value.trim(),cidade:$(`${p}Cidade`).value.trim(),uf:$(`${p}Uf`).value.trim().toUpperCase(),cep:$(`${p}Cep`).value.trim()}}
function editarCliente(id=''){const c=id?find('clientes',id):{};abrirModal(id?'Editar cliente':'Novo cliente',clienteForm(c),`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarCliente('${id}')">Salvar</button>`)}
async function salvarCliente(id){
  const nome=$('cNome').value.trim(),cpf=$('cCpf').value.trim();if(!nome||!cpf)return alert('Informe Nome/Razão Social e CPF/CNPJ.');
  const before=id?clone(find('clientes',id)):null, obj={tipoPessoa:$('cTipo').value,nomeRazao:nome,cpfCnpj:cpf,responsavel:$('cResp').value.trim(),cpfResponsavel:$('cCpfResp').value.trim(),segmento:$('cSegmento').value.trim(),telefone:$('cTel').value.trim(),telefoneReferencia:$('cTelRef').value.trim(),email:$('cEmail').value.trim(),origem:$('cOrigem').value.trim(),enderecoCadastral:modalAddress('cEnd'),enderecosInstalacao:[modalAddress('cInst')],ativo:true};
  if(id){const hist=[...(before.historicoCadastral||[])];if(JSON.stringify(before.enderecoCadastral)!==JSON.stringify(obj.enderecoCadastral)||before.responsavel!==obj.responsavel)hist.push({em:nowISO(),responsavelAnterior:before.responsavel||'',enderecoAnterior:before.enderecoCadastral||{}});obj.historicoCadastral=hist;await setDoc(COLS.clientes,id,obj);await audit('editar','Clientes',id,`Cliente ${nome} atualizado.`,before,obj)}else{const nid=await addDoc(COLS.clientes,{...obj,historicoCadastral:[]});await audit('criar','Clientes',nid,`Cliente ${nome} cadastrado.`,null,obj)}
  fecharModal();await refresh('Cliente salvo.')
}
function detalharCliente(id){const c=find('clientes',id), loc=active('locacoes').filter(x=>x.clienteId===id), ass=active('assistencias').filter(x=>x.clienteId===id), cb=active('cobrancas').filter(x=>x.clienteId===id);abrirModal(c.nomeRazao,`<div class="grid2"><div><div class="section-title">Cadastro</div><p>${esc(c.tipoPessoa)} · ${esc(c.cpfCnpj)}</p><p>Responsável: ${esc(c.responsavel||'—')}</p><p>${esc(c.telefone||'—')} · ${esc(c.email||'—')}</p><p>${esc(formatAddress(c.enderecoCadastral))}</p></div><div><div class="metric-row"><div class="metric"><span>Locações</span><strong>${loc.length}</strong></div><div class="metric"><span>Assistências</span><strong>${ass.length}</strong></div><div class="metric"><span>Cobranças</span><strong>${cb.length}</strong></div></div></div></div><div class="section-title">Locações</div>${loc.length?loc.map(x=>`<div class="metric"><span>${esc(x.status)}</span><strong style="font-size:13px">${dateBR(x.inicio)} → ${dateBR(x.termino)}</strong></div>`).join(''):empty('Sem locações.')}<div class="section-title">Histórico cadastral</div>${(c.historicoCadastral||[]).length?c.historicoCadastral.map(h=>`<div class="timeline-item"><strong>${dateTimeBR(h.em)}</strong><p>Responsável anterior: ${esc(h.responsavelAnterior||'—')} · ${esc(formatAddress(h.enderecoAnterior))}</p></div>`).join(''):empty('Sem alterações registradas.')}`,`<button class="btn ghost" onclick="fecharModal()">Fechar</button><button class="btn" onclick="fecharModal();editarCliente('${id}')">Editar</button>`)}
function formatAddress(a={}){return [a.logradouro,a.numero,a.complemento,a.bairro,a.cidade,a.uf,a.cep].filter(Boolean).join(', ')||'—'}
function filterTable(id,q){const n=normalize(q);document.querySelectorAll(`#${id} tbody tr`).forEach(tr=>tr.style.display=normalize(tr.dataset.search||tr.textContent).includes(n)?'':'none')}

