function viewEquipamentos(){
  const rows=active('equipamentos').sort((a,b)=>(a.tipo||'').localeCompare(b.tipo||'')||(a.serial||'').localeCompare(b.serial||''));
  return `<div class="card"><div class="row" style="align-items:center"><div><h2>Equipamentos</h2><p class="hint">Identificação operacional pelo número de série. Sem código interno obrigatório.</p></div><div class="inline-actions" style="justify-content:flex-end"><button class="btn ghost" onclick="downloadModeloCSV('equipamentos')">Modelo CSV</button><label class="btn ghost" style="display:inline-grid;place-items:center;margin:0">Importar CSV<input type="file" accept=".csv" hidden onchange="importarCSV(event,'equipamentos')"></label><button class="btn" onclick="editarEquipamento()">+ Novo equipamento</button></div></div><div class="tabs"><button class="tab active" onclick="renderEquipTab('lista',this)">Lista</button><button class="tab" onclick="renderEquipTab('agenda',this)">Disponibilidade / agenda</button></div><div id="equipTab">${equipTable(rows)}</div></div>`;
}
function equipTable(rows){return `<input class="search" id="eqSearch" placeholder="Pesquisar série, tipo, marca ou modelo..." oninput="filterTable('eqTable',this.value)">${rows.length?`<table id="eqTable"><thead><tr><th>Equipamento</th><th>Nº de série</th><th>Categoria</th><th>Situação</th><th>Local atual</th><th>Ações</th></tr></thead><tbody>${rows.map(e=>`<tr data-search="${esc([e.tipo,e.marca,e.modelo,e.serial,e.categoriaNome,e.situacao].join(' '))}"><td><b>${esc([e.tipo,e.marca,e.modelo].filter(Boolean).join(' '))}</b><br><span class="muted">${esc(e.tensao||'')}</span></td><td>${esc(e.serial)}</td><td>${esc(categoryName(e.categoriaId)||e.categoriaNome||'—')}</td><td>${tag(e.situacao||'Disponível',statusType(e.situacao))}</td><td>${esc(e.localAtual||'Safety')}</td><td><div class="inline-actions"><button class="btn small ghost" onclick="detalharEquipamento('${e.id}')">Abrir</button><button class="btn small ghost" onclick="editarEquipamento('${e.id}')">Editar</button><button class="btn small" onclick="novoTeste('${e.id}')">Teste</button></div></td></tr>`).join('')}</tbody></table>`:empty('Nenhum equipamento cadastrado.')}`}
function renderEquipTab(tab,btn){document.querySelectorAll('.tabs .tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$('equipTab').innerHTML=tab==='agenda'?availabilityHtml():equipTable(active('equipamentos'))}
function availabilityHtml(){
  const locs=active('locacoes').filter(x=>!['Encerrada','Cancelada'].includes(x.status));
  const rows=active('equipamentos').map(e=>{const uso=locs.flatMap(l=>(l.itens||[]).filter(i=>i.equipamentoId===e.id).map(i=>({l,i}))).sort((a,b)=>(a.l.inicio||'').localeCompare(b.l.inicio||''));return {e,uso}});
  return `<div class="notice blue">A agenda considera locações e reservas registradas. Equipamento devolvido permanece indisponível até a liberação técnica.</div><table><thead><tr><th>Equipamento</th><th>Situação</th><th>Compromissos</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(equipName(r.e.id))}</b></td><td>${tag(r.e.situacao||'Disponível',statusType(r.e.situacao))}</td><td>${r.uso.length?r.uso.map(u=>`<div>${dateBR(u.l.inicio)} → ${dateBR(u.l.termino)} · ${esc(clientName(u.l.clienteId))} · ${tag(u.l.status,statusType(u.l.status))}</div>`).join(''):tag('Sem reserva futura','ok')}</td></tr>`).join('')}</tbody></table>`;
}
function equipmentForm(e={}){return `<div class="grid2"><div><label>Categoria *</label><select id="eCat"><option value="">Selecione</option>${selectOptions(active('categorias'),e.categoriaId,x=>x.nome)}</select></div><div><label>Tipo / descrição *</label><input id="eTipo" value="${esc(e.tipo||'')}"></div><div><label>Fabricante / marca</label><input id="eMarca" value="${esc(e.marca||'')}"></div><div><label>Modelo</label><input id="eModelo" value="${esc(e.modelo||'')}"></div><div><label>Número de série *</label><input id="eSerial" value="${esc(e.serial||'')}"></div><div><label>Tensão / característica</label><input id="eTensao" value="${esc(e.tensao||'')}"></div><div><label>Situação</label><select id="eSituacao">${['Disponível','Reservado','Alugado','Emprestado','Aguardando teste','Em manutenção','Aguardando peça','Indisponível','Baixado'].map(s=>`<option ${e.situacao===s?'selected':''}>${s}</option>`).join('')}</select></div><div><label>Local atual</label><input id="eLocal" value="${esc(e.localAtual||'Safety')}"></div></div><label>Observações</label><textarea id="eObs">${esc(e.observacoes||'')}</textarea>`}
function editarEquipamento(id=''){const e=id?find('equipamentos',id):{};abrirModal(id?'Editar equipamento':'Novo equipamento',equipmentForm(e),`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarEquipamento('${id}')">Salvar</button>`)}
async function salvarEquipamento(id){const serial=$('eSerial').value.trim(),tipo=$('eTipo').value.trim();if(!serial||!tipo)return alert('Informe tipo e número de série.');const dup=data.equipamentos.find(x=>x.id!==id&&!x.excluido&&normalize(x.serial)===normalize(serial));if(dup)return alert('Já existe um equipamento com esse número de série.');const before=id?clone(find('equipamentos',id)):null,cat=find('categorias',$('eCat').value);const obj={categoriaId:$('eCat').value,categoriaNome:cat?.nome||'',tipo,marca:$('eMarca').value.trim(),modelo:$('eModelo').value.trim(),serial,tensao:$('eTensao').value.trim(),situacao:$('eSituacao').value,localAtual:$('eLocal').value.trim(),observacoes:$('eObs').value.trim(),ativo:true};if(id){await setDoc(COLS.equipamentos,id,obj);await audit('editar','Equipamentos',id,`Equipamento série ${serial} atualizado.`,before,obj)}else{const nid=await addDoc(COLS.equipamentos,obj);await audit('criar','Equipamentos',nid,`Equipamento série ${serial} cadastrado.`,null,obj)}fecharModal();await refresh('Equipamento salvo.')}
function detalharEquipamento(id){const e=find('equipamentos',id),tests=active('testes').filter(x=>x.equipamentoId===id).sort((a,b)=>(b.data||'').localeCompare(a.data||'')),movs=active('movimentos').filter(x=>x.equipamentoId===id||x.equipamentoAnteriorId===id||x.equipamentoNovoId===id).sort((a,b)=>(b.em||'').localeCompare(a.em||''));abrirModal(equipName(id),`<div class="grid2"><div><p>${tag(e.situacao,statusType(e.situacao))}</p><p>Categoria: <b>${esc(categoryName(e.categoriaId))}</b></p><p>Local: ${esc(e.localAtual||'—')}</p><p>${esc(e.observacoes||'')}</p></div><div class="metric-row"><div class="metric"><span>Testes</span><strong>${tests.length}</strong></div><div class="metric"><span>Movimentações</span><strong>${movs.length}</strong></div></div></div><div class="section-title">Últimos testes</div>${tests.length?tests.slice(0,5).map(t=>`<div class="metric"><span>${dateBR(t.data)} · ${esc(t.tipo||'Teste')}</span><strong style="font-size:13px">${esc(t.resultado)}</strong></div>`).join(''):empty('Nenhum teste registrado.')}<div class="section-title">Histórico</div>${movs.length?`<div class="timeline">${movs.slice(0,10).map(m=>`<div class="timeline-item"><strong>${esc(m.tipo||'Movimentação')} · ${dateTimeBR(m.em)}</strong><p>${esc(m.descricao||'')}</p></div>`).join('')}</div>`:empty('Sem movimentações registradas.')}`,`<button class="btn ghost" onclick="fecharModal()">Fechar</button><button class="btn ghost" onclick="fecharModal();editarEquipamento('${id}')">Editar</button><button class="btn" onclick="fecharModal();novoTeste('${id}')">Registrar teste</button>`)}
function novoTeste(equipId){const e=find('equipamentos',equipId),cat=find('categorias',e?.categoriaId),items=cat?.itensTeste||[];abrirModal('Registrar teste técnico',`<p><b>${esc(equipName(equipId))}</b></p><div class="grid2"><div><label>Data</label><input id="tData" type="date" value="${todayISO()}"></div><div><label>Tipo</label><select id="tTipo"><option>Teste de bancada</option><option>Liberação técnica</option><option>Preventiva</option><option>Teste final</option></select></div></div><div class="section-title">Checklist / parâmetros</div>${items.length?`<div class="check-grid">${items.map((x,i)=>`<div><label>${esc(x)}</label><input id="ti${i}" placeholder="Resultado / valor"></div>`).join('')}</div>`:`<div class="notice">Esta categoria ainda não possui modelo de teste configurado. É possível registrar observações e resultado geral.</div>`}<label>Observações</label><textarea id="tObs"></textarea><div class="grid2"><div><label>Resultado *</label><select id="tResultado"><option>Aprovado</option><option>Aprovado com observação</option><option>Reprovado</option></select></div><div><label>Após o teste, situação do equipamento</label><select id="tSituacao"><option>Disponível</option><option>Aguardando teste</option><option>Em manutenção</option><option>Indisponível</option></select></div></div>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarTeste('${equipId}')">Salvar teste</button>`)}
async function salvarTeste(equipId){const e=find('equipamentos',equipId),cat=find('categorias',e?.categoriaId),items=(cat?.itensTeste||[]).map((x,i)=>({item:x,valor:$(`ti${i}`)?.value||''})),obj={equipamentoId:equipId,categoriaId:e.categoriaId,data:$('tData').value,tipo:$('tTipo').value,itens,observacoes:$('tObs').value.trim(),resultado:$('tResultado').value,tecnicoUid:currentUser.uid,tecnicoNome:currentUser.nome};const id=await addDoc(COLS.testes,obj);await setDoc(COLS.equipamentos,equipId,{situacao:$('tSituacao').value});await audit('teste','Equipamentos',equipId,`Teste ${obj.tipo}: ${obj.resultado}.`);fecharModal();await refresh('Teste registrado.');perguntarAssinaturaTecnico('teste',id)}

