// ============================================================
function viewLocacoes(){
  const rows=active('locacoes').sort((a,b)=>(b.inicio||'').localeCompare(a.inicio||''));
  return `<div class="card"><div class="row" style="align-items:center"><div><h2>Locações</h2><p class="hint">Contratos curtos e longos, múltiplos equipamentos, reservas, prorrogações, substituições e devoluções.</p></div><div class="inline-actions" style="justify-content:flex-end"><button class="btn ghost" onclick="downloadModeloCSV('locacoes')">Modelo CSV</button><label class="btn ghost" style="display:inline-grid;place-items:center;margin:0">Importar CSV<input type="file" accept=".csv" hidden onchange="importarCSV(event,'locacoes')"></label><button class="btn" onclick="novaLocacao()">+ Nova locação</button></div></div>
  ${rows.length?`<table><thead><tr><th>Cliente</th><th>Período</th><th>Equipamentos</th><th>Valor mensal</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(l=>`<tr><td><b>${esc(clientName(l.clienteId))}</b><br><span class="muted">${esc(l.responsavel||'')}</span></td><td>${dateBR(l.inicio)} → ${dateBR(l.termino)}${l.prorrogacoes?.length?`<br><span class="muted">${l.prorrogacoes.length} prorrogação(ões)</span>`:''}</td><td>${(l.itens||[]).map(i=>`<div>${esc(i.serialSnapshot||find('equipamentos',i.equipamentoId)?.serial||'—')} · ${brl(i.valorMensal||0)}</div>`).join('')}</td><td><b>${brl((l.itens||[]).reduce((s,i)=>s+Number(i.valorMensal||0),0))}</b></td><td>${tag(l.status||'Preparação',statusType(l.status))}</td><td><div class="inline-actions"><button class="btn small ghost" onclick="detalharLocacao('${l.id}')">Abrir</button><button class="btn small ghost" onclick="editarLocacao('${l.id}')">Editar</button></div></td></tr>`).join('')}</tbody></table>`:empty('Nenhuma locação cadastrada.')}</div>`;
}
function rentalItemsHtml(items=[]){return `<div id="locItens">${items.map((i,idx)=>rentalItemRow(i,idx)).join('')}</div><button type="button" class="btn small ghost" onclick="adicionarItemLocacao()">+ Adicionar equipamento</button>`}
function rentalItemRow(i={},idx=Date.now()){const available=active('equipamentos').filter(e=>e.situacao==='Disponível'||e.situacao==='Reservado'||e.id===i.equipamentoId);return `<div class="grid3 rental-item" data-idx="${idx}" style="padding:10px;border:1px solid #e4e9ef;border-radius:10px;margin-bottom:8px"><div><label>Equipamento *</label><select class="liEquip"><option value="">Selecione</option>${selectOptions(available,i.equipamentoId,e=>equipName(e.id))}</select></div><div><label>Valor mensal negociado *</label><input class="liValor" value="${esc(i.valorMensal||'')}"></div><div><label>&nbsp;</label><button type="button" class="btn danger small" onclick="this.closest('.rental-item').remove()">Remover</button></div></div>`}
function novaLocacao(){editarLocacao('')}
function editarLocacao(id=''){const l=id?find('locacoes',id):{},cli=find('clientes',l.clienteId)||{};abrirModal(id?'Editar locação':'Nova locação',`<div class="grid2"><div><label>Cliente *</label><select id="lCliente" onchange="preencherDadosLocCliente()"><option value="">Selecione</option>${selectOptions(active('clientes'),l.clienteId,c=>c.nomeRazao+' · '+(c.cpfCnpj||''))}</select></div><div><label>Responsável</label><input id="lResp" value="${esc(l.responsavel||cli.responsavel||'')}"></div><div><label>Data inicial *</label><input id="lInicio" type="date" value="${esc(l.inicio||todayISO())}"></div><div><label>Data final prevista *</label><input id="lTermino" type="date" value="${esc(l.termino||'')}"></div><div><label>Tipo de documento</label><select id="lDocTipo"><option value="30dias" ${l.tipoDocumento==='30dias'?'selected':''}>Comprovante de entrega / até 30 dias</option><option value="contrato" ${l.tipoDocumento==='contrato'?'selected':''}>Contrato de locação</option></select></div><div><label>Dia de vencimento mensal</label><input id="lDiaVenc" type="number" min="1" max="31" value="${esc(l.diaVencimento||15)}"></div><div><label>Status</label><select id="lStatus">${['Preparação','Reservada','Aguardando teste','Liberada para entrega','Ativa','Encerrada','Cancelada'].map(s=>`<option ${l.status===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="section-title">Endereço de instalação</div>${addressForm('lInst',l.enderecoInstalacao||(cli.enderecosInstalacao||[])[0]||{})}<div class="section-title">Equipamentos</div>${rentalItemsHtml(l.itens||[])}<label>Observações</label><textarea id="lObs">${esc(l.observacoes||'')}</textarea>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarLocacao('${id}')">Salvar</button>`)}
function preencherDadosLocCliente(){const c=find('clientes',$('lCliente').value);if(!c)return;$('lResp').value=c.responsavel||'';const a=(c.enderecosInstalacao||[])[0]||c.enderecoCadastral||{};Object.entries({Log:a.logradouro,Num:a.numero,Comp:a.complemento,Bairro:a.bairro,Cidade:a.cidade,Uf:a.uf,Cep:a.cep}).forEach(([k,v])=>{const el=$(`lInst${k}`);if(el)el.value=v||''})}
function adicionarItemLocacao(){const d=document.createElement('div');d.innerHTML=rentalItemRow({},Date.now());$('locItens').appendChild(d.firstElementChild)}
function collectRentalItems(){return [...document.querySelectorAll('.rental-item')].map(r=>{const eid=r.querySelector('.liEquip').value,e=find('equipamentos',eid);return{equipamentoId:eid,serialSnapshot:e?.serial||'',descricaoSnapshot:equipName(eid),valorMensal:num(r.querySelector('.liValor').value)}}).filter(x=>x.equipamentoId)}
async function salvarLocacao(id){
  const cli=$('lCliente').value,itens=collectRentalItems(),inicio=$('lInicio').value,termino=$('lTermino').value;if(!cli||!inicio||!termino||!itens.length)return alert('Informe cliente, período e ao menos um equipamento.');
  if(termino<inicio)return alert('A data final não pode ser anterior à inicial.');
  const conflict=itens.find(i=>equipmentHasConflict(i.equipamentoId,inicio,termino,id));if(conflict)return alert(`O equipamento ${equipName(conflict.equipamentoId)} já possui compromisso nesse período.`);
  const before=id?clone(find('locacoes',id)):null,obj={clienteId:cli,responsavel:$('lResp').value.trim(),inicio,termino,tipoDocumento:$('lDocTipo').value,diaVencimento:Number($('lDiaVenc').value||15),status:$('lStatus').value,enderecoInstalacao:modalAddress('lInst'),itens,observacoes:$('lObs').value.trim(),prorrogacoes:before?.prorrogacoes||[],ativo:true};
  let lid=id;if(id){await setDoc(COLS.locacoes,id,obj);await audit('editar','Locações',id,`Locação de ${clientName(cli)} atualizada.`,before,obj)}else{lid=await addDoc(COLS.locacoes,obj);await audit('criar','Locações',lid,`Locação de ${clientName(cli)} criada.`,null,obj)}
  const allIds=new Set([...(before?.itens||[]).map(x=>x.equipamentoId),...itens.map(x=>x.equipamentoId)]);for(const eid of allIds){const inNew=itens.some(x=>x.equipamentoId===eid);if(!inNew&&find('equipamentos',eid)?.situacao==='Reservado')await setDoc(COLS.equipamentos,eid,{situacao:'Disponível'});else if(inNew&&['Preparação','Reservada','Aguardando teste','Liberada para entrega'].includes(obj.status))await setDoc(COLS.equipamentos,eid,{situacao:'Reservado'});else if(inNew&&obj.status==='Ativa')await setDoc(COLS.equipamentos,eid,{situacao:'Alugado',localAtual:formatAddress(obj.enderecoInstalacao)})}
  fecharModal();await refresh('Locação salva.')
}
function equipmentHasConflict(eid,start,end,ignoreLoc=''){return active('locacoes').some(l=>l.id!==ignoreLoc&&!['Encerrada','Cancelada'].includes(l.status)&&(l.itens||[]).some(i=>i.equipamentoId===eid)&&!(end<l.inicio||start>l.termino))}
function detalharLocacao(id){const l=find('locacoes',id),cb=active('cobrancas').filter(x=>x.locacaoId===id).sort((a,b)=>(b.competencia||'').localeCompare(a.competencia||'')),mov=active('movimentos').filter(x=>x.locacaoId===id);abrirModal(`Locação · ${clientName(l.clienteId)}`,`<div class="grid2"><div><p>${tag(l.status,statusType(l.status))}</p><p><b>${dateBR(l.inicio)} → ${dateBR(l.termino)}</b></p><p>${esc(formatAddress(l.enderecoInstalacao))}</p><p>Responsável: ${esc(l.responsavel||'—')}</p></div><div class="metric-row"><div class="metric"><span>Valor mensal</span><strong>${brl((l.itens||[]).reduce((s,i)=>s+Number(i.valorMensal||0),0))}</strong></div><div class="metric"><span>Cobranças</span><strong>${cb.length}</strong></div></div></div><div class="section-title">Equipamentos</div>${(l.itens||[]).map(i=>`<div class="metric"><span>${esc(i.serialSnapshot||'')}</span><strong style="font-size:13px">${esc(i.descricaoSnapshot||equipName(i.equipamentoId))} · ${brl(i.valorMensal)}</strong></div>`).join('')}<div class="section-title">Cobranças recentes</div>${cb.length?cb.slice(0,5).map(c=>`<div class="metric"><span>${monthLabel(c.competencia)} · venc. ${dateBR(c.vencimento)}</span><strong style="font-size:13px">${brl(c.valor)} · ${esc(paymentStatus(c))}</strong></div>`).join(''):empty('Sem cobranças lançadas.')}<div class="section-title">Movimentações</div>${mov.length?`<div class="timeline">${mov.map(m=>`<div class="timeline-item"><strong>${esc(m.tipo)} · ${dateTimeBR(m.em)}</strong><p>${esc(m.descricao||'')}</p>${m.tipo==='Empréstimo'&&m.status!=='Devolvido'?`<button class="btn small ghost" onclick="devolverEmprestimo('${m.id}')">Registrar devolução do empréstimo</button>`:''}</div>`).join('')}</div>`:empty('Sem movimentações.')}`,`<button class="btn ghost" onclick="fecharModal()">Fechar</button><button class="btn ghost" onclick="prorrogarLocacao('${id}')">Prorrogar</button><button class="btn ghost" onclick="trocarResponsavelLocacao('${id}')">Trocar responsável</button><button class="btn ghost" onclick="alterarEnderecoLocacao('${id}')">Alterar endereço</button><button class="btn ghost" onclick="trocarEquipamento('${id}')">Substituir equipamento</button><button class="btn ghost" onclick="registrarVistoria('${id}')">Vistoria</button><button class="btn gold" onclick="gerarDocumentoLocacao('${id}')">Gerar documento</button><button class="btn" onclick="fecharModal();editarLocacao('${id}')">Editar</button>`)}
async function prorrogarLocacao(id){const l=find('locacoes',id),nova=prompt('Nova data final (AAAA-MM-DD):',l.termino);if(!nova||nova<=l.termino)return;if((l.itens||[]).some(i=>equipmentHasConflict(i.equipamentoId,l.termino,nova,id)))return alert('Existe conflito de agenda para um dos equipamentos no novo período.');const hist=[...(l.prorrogacoes||[]),{de:l.termino,para:nova,em:nowISO(),uid:currentUser.uid}];await setDoc(COLS.locacoes,id,{termino:nova,prorrogacoes:hist});await audit('prorrogar','Locações',id,`Locação prorrogada de ${dateBR(l.termino)} para ${dateBR(nova)}.`);fecharModal();await refresh('Locação prorrogada.')}
async function trocarResponsavelLocacao(id){const l=find('locacoes',id),novo=prompt('Nome do novo responsável:',l.responsavel||'');if(!novo||novo===l.responsavel)return;const inicio=prompt('Data de início da responsabilidade/novo contrato (AAAA-MM-DD):',todayISO());if(!inicio)return;const novoObj={...clone(l),responsavel:novo,inicio,prorrogacoes:[],status:'Ativa',criadoEm:undefined,criadoPor:undefined,alteradoEm:undefined,alteradoPor:undefined};delete novoObj.id;const novoId=await addDoc(COLS.locacoes,novoObj);await setDoc(COLS.locacoes,id,{status:'Encerrada',termino:inicio,encerramentoMotivo:'Troca de responsável',substituidaPorLocacaoId:novoId});await addDoc(COLS.movimentos,{tipo:'Troca de responsável',locacaoId:novoId,clienteId:l.clienteId,descricao:`Responsável alterado de ${l.responsavel||'—'} para ${novo}. Novo contrato/locação ${novoId}.`,em:nowISO()});await audit('troca_responsavel','Locações',id,`Novo contrato criado por troca de responsável: ${novoId}.`);fecharModal();await refresh('Novo contrato criado para o novo responsável.')}
function alterarEnderecoLocacao(id){const l=find('locacoes',id);abrirModal('Alterar endereço de instalação',`${addressForm('aeLoc',l.enderecoInstalacao||{})}<label>Motivo / observação</label><textarea id="aeObs"></textarea>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarEnderecoLocacao('${id}')">Salvar alteração</button>`)}
async function salvarEnderecoLocacao(id){const l=find('locacoes',id),antigo=clone(l.enderecoInstalacao||{}),novo=modalAddress('aeLoc');await setDoc(COLS.locacoes,id,{enderecoInstalacao:novo});for(const i of l.itens||[])await setDoc(COLS.equipamentos,i.equipamentoId,{localAtual:formatAddress(novo)});await addDoc(COLS.movimentos,{tipo:'Alteração de endereço',locacaoId:id,clienteId:l.clienteId,descricao:`Endereço alterado de ${formatAddress(antigo)} para ${formatAddress(novo)}. ${$('aeObs').value.trim()}`,em:nowISO()});await audit('endereco','Locações',id,'Endereço de instalação alterado.',antigo,novo);fecharModal();await refresh('Endereço atualizado e registrado no histórico.')}
function trocarEquipamento(locId){const l=find('locacoes',locId);abrirModal('Substituição de equipamento',`<div class="grid2"><div><label>Equipamento que será retirado</label><select id="trOld">${(l.itens||[]).map(i=>`<option value="${i.equipamentoId}">${esc(i.descricaoSnapshot||equipName(i.equipamentoId))}</option>`).join('')}</select></div><div><label>Novo equipamento disponível</label><select id="trNew"><option value="">Selecione</option>${selectOptions(active('equipamentos').filter(e=>e.situacao==='Disponível'),'',e=>equipName(e.id))}</select></div></div><label>Motivo / observação</label><textarea id="trMotivo"></textarea>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarTroca('${locId}')">Registrar troca</button>`)}
async function salvarTroca(locId){const l=find('locacoes',locId),oldId=$('trOld').value,newId=$('trNew').value;if(!newId)return alert('Selecione o equipamento substituto.');const oldItem=(l.itens||[]).find(i=>i.equipamentoId===oldId),newE=find('equipamentos',newId),itens=(l.itens||[]).map(i=>i.equipamentoId===oldId?{...i,equipamentoId:newId,serialSnapshot:newE.serial,descricaoSnapshot:equipName(newId)}:i);await setDoc(COLS.locacoes,locId,{itens});await setDoc(COLS.equipamentos,oldId,{situacao:'Aguardando teste',localAtual:'Safety'});await setDoc(COLS.equipamentos,newId,{situacao:'Alugado',localAtual:formatAddress(l.enderecoInstalacao)});const mid=await addDoc(COLS.movimentos,{tipo:'Substituição',locacaoId:locId,clienteId:l.clienteId,equipamentoAnteriorId:oldId,equipamentoNovoId:newId,equipamentoId:newId,descricao:`${equipName(oldId)} substituído por ${equipName(newId)}. ${$('trMotivo').value.trim()}`,em:nowISO(),assinaturaClienteVetorial:''});await audit('substituir','Locações',locId,`Equipamento substituído. Movimento ${mid}.`);fecharModal();await refresh('Substituição registrada.');perguntarAssinaturaClienteMovimento(mid)}
function registrarVistoria(locId){const l=find('locacoes',locId);abrirModal('Vistoria de equipamento',`<div class="grid2"><div><label>Tipo</label><select id="vTipo" onchange="renderVistoriaChecklist()"><option>Saída</option><option>Retorno</option></select></div><div><label>Equipamento</label><select id="vEquip" onchange="renderVistoriaChecklist()">${(l.itens||[]).map(i=>`<option value="${i.equipamentoId}">${esc(equipName(i.equipamentoId))}</option>`).join('')}</select></div></div><div class="section-title">Checklist da categoria</div><div id="vChecklist"></div><label>Condição geral / avarias</label><textarea id="vObs"></textarea><p class="hint">Na V1 a vistoria registra checklist e observações. Fotos/evidências ficam para a V2.</p>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarVistoria('${locId}')">Salvar vistoria</button>`);setTimeout(renderVistoriaChecklist,0)}
function renderVistoriaChecklist(){const eid=$('vEquip')?.value,tipo=$('vTipo')?.value,e=find('equipamentos',eid),cat=find('categorias',e?.categoriaId),items=tipo==='Retorno'?(cat?.checklistRetorno||[]):(cat?.checklistSaida||[]),box=$('vChecklist');if(!box)return;box.innerHTML=items.length?`<div class="check-grid">${items.map((x,i)=>`<label class="check-item"><input type="checkbox" class="vCheck" value="${esc(x)}"> ${esc(x)}</label>`).join('')}</div>`:`<div class="notice">A categoria deste equipamento não possui checklist de ${normalize(tipo)} configurado. Registre a condição e as evidências abaixo.</div>`}
async function salvarVistoria(locId){const checklist=[...document.querySelectorAll('.vCheck')].map(x=>({item:x.value,ok:x.checked}));const obj={locacaoId:locId,equipamentoId:$('vEquip').value,tipo:$('vTipo').value,data:todayISO(),checklist,observacoes:$('vObs').value.trim(),tecnicoUid:currentUser.uid,tecnicoNome:currentUser.nome};const id=await addDoc(COLS.vistorias,obj);await audit('vistoria','Locações',locId,`Vistoria de ${obj.tipo} registrada.`);fecharModal();await refresh('Vistoria salva.');perguntarAssinaturaTecnico('vistoria',id)}

// ============================================================
// Assistência técnica, garantia e empréstimo
// ============================================================
function viewAssistencias(){const rows=active('assistencias').sort((a,b)=>(b.entrada||'').localeCompare(a.entrada||''));return `<div class="card"><div class="row" style="align-items:center"><div><h2>Assistência Técnica</h2><p class="hint">Equipamentos dos clientes: particular, garantia, diagnóstico, orçamento, manutenção, testes e empréstimos.</p></div><div class="inline-actions" style="justify-content:flex-end"><button class="btn" onclick="editarAssistencia()">+ Nova entrada</button></div></div>${rows.length?`<table><thead><tr><th>Entrada</th><th>Cliente</th><th>Equipamento</th><th>Tipo</th><th>Status</th><th>Orçamento</th><th>Ações</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${dateBR(a.entrada)}</td><td><b>${esc(clientName(a.clienteId))}</b></td><td>${esc([a.equipamentoTipo,a.marca,a.modelo].filter(Boolean).join(' '))}<br><span class="muted">Série ${esc(a.serial||'—')}</span></td><td>${tag(a.tipoAtendimento||'Particular','info')}</td><td>${tag(a.status||'Recebido',statusType(a.status))}</td><td>${a.orcamentoValor?brl(a.orcamentoValor):'—'}<br><span class="muted">${esc(a.orcamentoStatus||'')}</span></td><td><div class="inline-actions"><button class="btn small ghost" onclick="detalharAssistencia('${a.id}')">Abrir</button><button class="btn small ghost" onclick="editarAssistencia('${a.id}')">Editar</button></div></td></tr>`).join('')}</tbody></table>`:empty('Nenhum atendimento cadastrado.')}</div>`}
function editarAssistencia(id=''){const a=id?find('assistencias',id):{};abrirModal(id?'Editar assistência':'Nova entrada de assistência',`<div class="grid2"><div><label>Cliente *</label><select id="aCliente"><option value="">Selecione</option>${selectOptions(active('clientes'),a.clienteId,c=>c.nomeRazao)}</select></div><div><label>Tipo de atendimento</label><select id="aTipo"><option ${a.tipoAtendimento==='Particular'?'selected':''}>Particular</option><option ${a.tipoAtendimento==='Garantia'?'selected':''}>Garantia</option></select></div><div><label>Data de entrada</label><input id="aEntrada" type="date" value="${esc(a.entrada||todayISO())}"></div><div><label>Status</label><select id="aStatus">${['Recebido','Em bancada / diagnóstico','Orçamento em elaboração','Aguardando aprovação','Orçamento aprovado','Orçamento recusado','Em manutenção','Aguardando peça','Em testes','Liberado','Entregue','Cancelada'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div><label>Categoria</label><select id="aCat"><option value="">Selecione</option>${selectOptions(active('categorias'),a.categoriaId,c=>c.nome)}</select></div><div><label>Tipo de equipamento *</label><input id="aEqTipo" value="${esc(a.equipamentoTipo||'')}"></div><div><label>Fabricante / marca</label><input id="aMarca" value="${esc(a.marca||'')}"></div><div><label>Modelo</label><input id="aModelo" value="${esc(a.modelo||'')}"></div><div><label>Número de série *</label><input id="aSerial" value="${esc(a.serial||'')}"></div><div><label>Acessórios recebidos</label><input id="aAcess" value="${esc(a.acessorios||'')}"></div><div><label>Fabricante da garantia</label><input id="aFabGarantia" value="${esc(a.fabricanteGarantia||'')}"></div><div><label>Referência / protocolo da garantia</label><input id="aGarantiaRef" value="${esc(a.garantiaReferencia||'')}"></div></div><label>Defeito relatado pelo cliente</label><textarea id="aDefeito">${esc(a.defeitoRelatado||'')}</textarea><label>Diagnóstico técnico</label><textarea id="aDiag">${esc(a.diagnostico||'')}</textarea><div class="grid2"><div><label>Valor do orçamento</label><input id="aOrcValor" value="${esc(a.orcamentoValor||'')}"></div><div><label>Status do orçamento</label><select id="aOrcStatus"><option></option><option ${a.orcamentoStatus==='Aguardando cliente'?'selected':''}>Aguardando cliente</option><option ${a.orcamentoStatus==='Aprovado'?'selected':''}>Aprovado</option><option ${a.orcamentoStatus==='Recusado'?'selected':''}>Recusado</option></select></div></div><label>Serviços propostos / executados</label><textarea id="aServicos">${esc(a.servicos||'')}</textarea><label>Observações</label><textarea id="aObs">${esc(a.observacoes||'')}</textarea>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarAssistencia('${id}')">Salvar</button>`)}
async function salvarAssistencia(id){const cli=$('aCliente').value,tipo=$('aEqTipo').value.trim(),serial=$('aSerial').value.trim();if(!cli||!tipo||!serial)return alert('Informe cliente, equipamento e número de série.');const before=id?clone(find('assistencias',id)):null,obj={clienteId:cli,tipoAtendimento:$('aTipo').value,entrada:$('aEntrada').value,status:$('aStatus').value,categoriaId:$('aCat').value,equipamentoTipo:tipo,marca:$('aMarca').value.trim(),modelo:$('aModelo').value.trim(),serial,acessorios:$('aAcess').value.trim(),fabricanteGarantia:$('aFabGarantia').value.trim(),garantiaReferencia:$('aGarantiaRef').value.trim(),defeitoRelatado:$('aDefeito').value.trim(),diagnostico:$('aDiag').value.trim(),orcamentoValor:num($('aOrcValor').value),orcamentoStatus:$('aOrcStatus').value,servicos:$('aServicos').value.trim(),observacoes:$('aObs').value.trim(),ativo:true};let aid=id;if(id){await setDoc(COLS.assistencias,id,obj);await audit('editar','Assistência',id,`Assistência série ${serial} atualizada.`,before,obj)}else{aid=await addDoc(COLS.assistencias,obj);await audit('criar','Assistência',aid,`Entrada de assistência série ${serial}.`,null,obj)}fecharModal();await refresh('Atendimento salvo.')}
function detalharAssistencia(id){const a=find('assistencias',id),mov=active('movimentos').filter(x=>x.assistenciaId===id),tests=active('testes').filter(x=>x.assistenciaId===id);abrirModal(`Assistência · Série ${a.serial}`,`<div class="grid2"><div><p>${tag(a.status,statusType(a.status))} ${tag(a.tipoAtendimento,'info')}</p><p><b>${esc(clientName(a.clienteId))}</b></p><p>${esc([a.equipamentoTipo,a.marca,a.modelo].filter(Boolean).join(' '))}</p><p>Entrada: ${dateBR(a.entrada)}</p></div><div class="metric-row"><div class="metric"><span>Orçamento</span><strong>${brl(a.orcamentoValor||0)}</strong></div><div class="metric"><span>Empréstimos</span><strong>${mov.filter(x=>x.tipo==='Empréstimo').length}</strong></div></div></div><div class="section-title">Relato / diagnóstico</div><p><b>Relato:</b> ${esc(a.defeitoRelatado||'—')}</p><p><b>Diagnóstico:</b> ${esc(a.diagnostico||'—')}</p><p><b>Serviços:</b> ${esc(a.servicos||'—')}</p><div class="section-title">Movimentações</div>${mov.length?`<div class="timeline">${mov.map(m=>`<div class="timeline-item"><strong>${esc(m.tipo)} · ${dateTimeBR(m.em)}</strong><p>${esc(m.descricao||'')}</p>${m.tipo==='Empréstimo'&&m.status!=='Devolvido'?`<button class="btn small ghost" onclick="devolverEmprestimo('${m.id}')">Registrar devolução do empréstimo</button>`:''}</div>`).join('')}</div>`:empty('Sem movimentações.')}`,`<button class="btn ghost" onclick="fecharModal()">Fechar</button><button class="btn ghost" onclick="emprestarEquipamento('${id}')">Emprestar equipamento</button><button class="btn ghost" onclick="registrarTesteAssistencia('${id}')">Registrar teste</button><button class="btn gold" onclick="gerarDocumentoAssistencia('${id}')">Gerar documento</button><button class="btn" onclick="fecharModal();editarAssistencia('${id}')">Editar</button>`)}
function emprestarEquipamento(aid){const a=find('assistencias',aid);abrirModal('Empréstimo durante assistência',`<p>Cliente: <b>${esc(clientName(a.clienteId))}</b></p><label>Equipamento da Safety</label><select id="emEquip"><option value="">Selecione</option>${selectOptions(active('equipamentos').filter(e=>e.situacao==='Disponível'),'',e=>equipName(e.id))}</select><div class="grid2"><div><label>Data de saída</label><input id="emData" type="date" value="${todayISO()}"></div><div><label>Previsão de retorno</label><input id="emRet" type="date"></div></div><label>Observações</label><textarea id="emObs"></textarea>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarEmprestimo('${aid}')">Registrar</button>`)}
async function salvarEmprestimo(aid){const a=find('assistencias',aid),eid=$('emEquip').value;if(!eid)return alert('Selecione o equipamento.');const id=await addDoc(COLS.movimentos,{tipo:'Empréstimo',assistenciaId:aid,clienteId:a.clienteId,equipamentoId:eid,saida:$('emData').value,retornoPrevisto:$('emRet').value,descricao:`Equipamento ${equipName(eid)} emprestado enquanto o equipamento série ${a.serial} permanece em assistência. ${$('emObs').value.trim()}`,em:nowISO(),status:'Em aberto'});await setDoc(COLS.equipamentos,eid,{situacao:'Emprestado',localAtual:clientName(a.clienteId)});await audit('emprestimo','Assistência',aid,`Empréstimo ${id} registrado.`);fecharModal();await refresh('Empréstimo registrado.')}
async function devolverEmprestimo(mid){const m=find('movimentos',mid);if(!m||m.tipo!=='Empréstimo')return;if(!confirm('Confirmar a devolução do equipamento emprestado? Ele ficará Aguardando teste antes de voltar a disponível.'))return;await setDoc(COLS.movimentos,mid,{status:'Devolvido',retornoEm:todayISO()});await setDoc(COLS.equipamentos,m.equipamentoId,{situacao:'Aguardando teste',localAtual:'Safety'});await audit('devolucao_emprestimo','Assistência',m.assistenciaId,`Empréstimo ${mid} devolvido.`);fecharModal();await refresh('Devolução registrada. O equipamento aguarda teste técnico.')}
function registrarTesteAssistencia(aid){const a=find('assistencias',aid),cat=find('categorias',a.categoriaId),items=cat?.itensTeste||[];abrirModal('Teste técnico da assistência',`<p>${esc(a.equipamentoTipo)} · Série ${esc(a.serial)}</p><div class="grid2"><div><label>Data</label><input id="atData" type="date" value="${todayISO()}"></div><div><label>Tipo</label><select id="atTipo"><option>Teste de bancada</option><option>Teste final</option><option>Manutenção preventiva</option></select></div></div>${items.length?items.map((x,i)=>`<label>${esc(x)}</label><input id="ati${i}">`).join(''):''}<label>Observações</label><textarea id="atObs"></textarea><label>Resultado</label><select id="atResultado"><option>Aprovado</option><option>Aprovado com observação</option><option>Reprovado</option></select>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarTesteAssistencia('${aid}')">Salvar</button>`)}
async function salvarTesteAssistencia(aid){const a=find('assistencias',aid),cat=find('categorias',a.categoriaId),items=(cat?.itensTeste||[]).map((x,i)=>({item:x,valor:$(`ati${i}`)?.value||''})),obj={assistenciaId:aid,clienteId:a.clienteId,categoriaId:a.categoriaId,serial:a.serial,data:$('atData').value,tipo:$('atTipo').value,itens,observacoes:$('atObs').value.trim(),resultado:$('atResultado').value,tecnicoUid:currentUser.uid,tecnicoNome:currentUser.nome};const id=await addDoc(COLS.testes,obj);await audit('teste','Assistência',aid,`Teste ${obj.tipo}: ${obj.resultado}.`);fecharModal();await refresh('Teste registrado.');perguntarAssinaturaTecnico('teste',id)}

