// ============================================================
function viewDocumentos(){
  const rows=active('documentos').sort((a,b)=>(b.criadoEm||'').localeCompare(a.criadoEm||''));
  const mov=active('movimentos').filter(x=>x.tipo==='Substituição'||x.tipo==='Empréstimo');
  return `<div class="card"><h2>Documentos</h2><p class="hint">A V1 não armazena PDF nem fotos. O sistema guarda somente os dados do registro e as assinaturas eletrônicas em formato vetorial; o PDF é gerado localmente no aparelho quando necessário.</p>
  <div class="grid3">${rows.slice(0,20).map(d=>`<div class="doc-card"><h4>${esc(d.tipo)}</h4><p class="hint">${dateTimeBR(d.criadoEm)} · ${esc(d.referencia||'')}</p><p>${d.assinaturaClienteVetorial?tag('Cliente assinou','ok'):tag('Cliente sem assinatura','info')} ${d.assinaturaTecnicoVetorial?tag('Técnico assinou','ok'):tag('Técnico sem assinatura','info')}</p><div class="inline-actions"><button class="btn small ghost" onclick="assinarDocumento('${d.id}','tecnico')">Assinar técnico</button><button class="btn small ghost" onclick="assinarDocumento('${d.id}','cliente')">Assinar cliente</button><button class="btn small" onclick="reabrirDocumento('${d.id}')">Gerar PDF</button></div></div>`).join('')||empty('Nenhum documento gerado.')}</div>
  <div class="section-title">Substituições / empréstimos</div>${mov.length?`<table><thead><tr><th>Tipo</th><th>Cliente</th><th>Data</th><th>Assinatura do cliente</th><th>Ações</th></tr></thead><tbody>${mov.map(m=>`<tr><td>${esc(m.tipo)}</td><td>${esc(clientName(m.clienteId))}</td><td>${dateTimeBR(m.em)}</td><td>${m.assinaturaClienteVetorial?tag('Assinado','ok'):tag('Pendente','warn')}</td><td><div class="inline-actions"><button class="btn small ghost" onclick="perguntarAssinaturaClienteMovimento('${m.id}')">Assinar cliente</button><button class="btn small" onclick="gerarDocumentoMovimento('${m.id}')">Preparar documento</button></div></td></tr>`).join('')}</tbody></table>`:empty('Nenhuma movimentação com documento.')}</div>`
}
function perguntarAssinaturaClienteMovimento(mid){openSignature({collection:COLS.movimentos,id:mid,field:'assinaturaClienteVetorial',title:'Assinatura do cliente',hint:'Entregue o celular ao cliente para que ele assine no campo abaixo.'})}
function perguntarAssinaturaTecnico(tipo,id){if(confirm('Deseja assinar eletronicamente este registro como técnico responsável?'))openSignature({collection:tipo==='teste'?COLS.testes:COLS.vistorias,id,field:'assinaturaTecnicoVetorial',title:'Assinatura do técnico responsável',hint:'Assine abaixo para validar o registro técnico.'})}
function assinarDocumento(docId,tipo){
  const cliente=tipo==='cliente';
  openSignature({collection:COLS.documentos,id:docId,field:cliente?'assinaturaClienteVetorial':'assinaturaTecnicoVetorial',title:cliente?'Assinatura do cliente / responsável':'Assinatura do técnico responsável',hint:cliente?'Entregue o aparelho ao cliente ou responsável para assinatura.':'Assine abaixo para validar este documento.'});
}
function openSignature(target){signatureTarget=target;signatureStrokes=[];signatureCurrentStroke=null;$('signatureTitle').textContent=target.title;$('signatureHint').textContent=target.hint||'Assine abaixo.';$('signatureModal').classList.remove('hidden');setTimeout(resizeSignatureCanvas,50)}
function fecharAssinatura(){$('signatureModal').classList.add('hidden');signatureTarget=null;signatureStrokes=[];signatureCurrentStroke=null}
function resizeSignatureCanvas(){const c=$('signatureCanvas'),r=c.getBoundingClientRect(),dpr=Math.max(1,window.devicePixelRatio||1);c.width=Math.floor(r.width*dpr);c.height=Math.floor(r.height*dpr);signatureCaptureSize={w:Math.max(1,r.width),h:Math.max(1,r.height)};const ctx=c.getContext('2d');ctx.scale(dpr,dpr);ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#123d6b';signatureLast=null}
function sigPoint(ev){const c=$('signatureCanvas'),r=c.getBoundingClientRect(),t=ev.touches?.[0]||ev;return{x:Math.max(0,Math.min(r.width,t.clientX-r.left)),y:Math.max(0,Math.min(r.height,t.clientY-r.top))}}
function sigStart(ev){signatureDrawing=true;signatureLast=sigPoint(ev);signatureCurrentStroke=[signatureLast];signatureStrokes.push(signatureCurrentStroke);ev.preventDefault()}
function sigMove(ev){if(!signatureDrawing)return;const p=sigPoint(ev),ctx=$('signatureCanvas').getContext('2d');if(Math.hypot(p.x-signatureLast.x,p.y-signatureLast.y)<1.5){ev.preventDefault();return}ctx.beginPath();ctx.moveTo(signatureLast.x,signatureLast.y);ctx.lineTo(p.x,p.y);ctx.stroke();signatureLast=p;signatureCurrentStroke.push(p);ev.preventDefault()}
function sigEnd(){signatureDrawing=false;signatureLast=null;signatureCurrentStroke=null}
function limparAssinatura(){const c=$('signatureCanvas'),ctx=c.getContext('2d');ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,c.width,c.height);ctx.restore();signatureStrokes=[];signatureCurrentStroke=null}
async function salvarAssinatura(){
  if(!signatureTarget)return;
  const pts=signatureStrokes.reduce((n,s)=>n+s.length,0);if(pts<4)return alert('Faça a assinatura antes de salvar.');
  const payload=JSON.stringify({w:Math.round(signatureCaptureSize.w),h:Math.round(signatureCaptureSize.h),strokes:signatureStrokes.map(st=>st.map(p=>({x:+p.x.toFixed(1),y:+p.y.toFixed(1)})))});
  await setDoc(signatureTarget.collection,signatureTarget.id,{[signatureTarget.field]:payload,[`${signatureTarget.field}Em`]:nowISO(),[`${signatureTarget.field}ColetadaPor`]:currentUser.uid,[`${signatureTarget.field}ColetadaPorNome`]:currentUser.nome});
  await audit('assinatura','Documentos',signatureTarget.id,`${signatureTarget.title} registrada eletronicamente em formato vetorial.`);fecharAssinatura();await refresh('Assinatura salva.');
}
$('signatureCanvas').addEventListener('mousedown',sigStart);$('signatureCanvas').addEventListener('mousemove',sigMove);window.addEventListener('mouseup',sigEnd);$('signatureCanvas').addEventListener('touchstart',sigStart,{passive:false});$('signatureCanvas').addEventListener('touchmove',sigMove,{passive:false});$('signatureCanvas').addEventListener('touchend',sigEnd);

function signatureSvg(data,label,name=''){
  if(!data)return `<div class="pdf-sign"><div style="height:70px"></div><div class="pdf-line">${esc(label)}${name?` · ${esc(name)}`:''}</div></div>`;
  try{const d=typeof data==='string'?JSON.parse(data):data,w=Number(d.w)||500,h=Number(d.h)||180,lines=(d.strokes||[]).map(st=>`<polyline points="${st.map(p=>`${Number(p.x)||0},${Number(p.y)||0}`).join(' ')}" fill="none" stroke="#123d6b" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>`).join('');return `<div class="pdf-sign"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="xMidYMid meet" style="width:200px;height:70px;display:block;margin:0 auto">${lines}</svg><div class="pdf-line">${esc(label)}${name?` · ${esc(name)}`:''}</div></div>`}catch(e){return `<div class="pdf-sign"><div style="height:70px"></div><div class="pdf-line">${esc(label)}${name?` · ${esc(name)}`:''}</div></div>`}
}
function documentSignatures(d){return `<div class="pdf-signatures">${signatureSvg(d.assinaturaTecnicoVetorial,'Técnico / Safety',d.assinaturaTecnicoNome||'')}${signatureSvg(d.assinaturaClienteVetorial,'Cliente / responsável',d.assinaturaClienteNome||'')}</div>`}
function aplicarAssinaturasDocumento(html,d){const bloco=documentSignatures(d);return html.includes('<div class="pdf-footer">')?html.replace('<div class="pdf-footer">',bloco+'<div class="pdf-footer">'):html+bloco}

function gerarDocumentoLocacao(id){const l=find('locacoes',id),tipo=l.tipoDocumento==='30dias'?'Comprovante de Entrega de Equipamento':'Contrato de Locação de Equipamentos';criarEGerarDocumento({tipo,referencia:`Locação ${id}`,entidade:'locacao',entidadeId:id,html:docLocacao(l,tipo)})}
function gerarDocumentoAssistencia(id){const a=find('assistencias',id);abrirModal('Preparar documento',`<p>Selecione o documento para este atendimento.</p><div class="grid2"><button class="btn ghost" onclick="fecharModal();criarEGerarDocumento({tipo:'Orçamento',referencia:'Assistência ${id}',entidade:'assistencia',entidadeId:'${id}',html:docOrcamento(find('assistencias','${id}'))})">Orçamento</button><button class="btn ghost" onclick="fecharModal();criarEGerarDocumento({tipo:'Relatório de Manutenção',referencia:'Assistência ${id}',entidade:'assistencia',entidadeId:'${id}',html:docRelatorio(find('assistencias','${id}')),assinaturaTecnicoVetorial:assinaturaTecnicaAssistencia('${id}')})">Relatório de manutenção</button><button class="btn ghost" onclick="fecharModal();criarEGerarDocumento({tipo:'Recibo',referencia:'Assistência ${id}',entidade:'assistencia',entidadeId:'${id}',html:docRecibo(find('assistencias','${id}'))})">Recibo</button></div>`) }
function assinaturaTecnicaAssistencia(id){const t=active('testes').filter(x=>x.assistenciaId===id&&x.assinaturaTecnicoVetorial).sort((a,b)=>(b.data||'').localeCompare(a.data||''))[0];return t?.assinaturaTecnicoVetorial||''}
function gerarDocumentoMovimento(id){const m=find('movimentos',id);criarEGerarDocumento({tipo:m.tipo==='Substituição'?'Substituição de Equipamento':'Termo de Empréstimo',referencia:`Movimento ${id}`,entidade:'movimento',entidadeId:id,html:docMovimento(m),assinaturaClienteVetorial:m.assinaturaClienteVetorial||''})}
async function criarEGerarDocumento(opts){
  const did=await addDoc(COLS.documentos,{tipo:opts.tipo,referencia:opts.referencia,entidade:opts.entidade,entidadeId:opts.entidadeId,assinaturaClienteVetorial:opts.assinaturaClienteVetorial||'',assinaturaTecnicoVetorial:opts.assinaturaTecnicoVetorial||'',html:opts.html});
  await audit('preparar','Documentos',did,`${opts.tipo} preparado. O PDF não é armazenado.`);await refresh(null,false);
  abrirModal('Documento preparado',`<p><b>${esc(opts.tipo)}</b> foi preparado.</p><p class="hint">Colete as assinaturas necessárias e depois gere o PDF. O arquivo PDF será criado somente no aparelho e não será salvo no sistema.</p>`, `<button class="btn ghost" onclick="fecharModal();assinarDocumento('${did}','tecnico')">Assinar técnico</button><button class="btn ghost" onclick="fecharModal();assinarDocumento('${did}','cliente')">Assinar cliente</button><button class="btn" onclick="fecharModal();reabrirDocumento('${did}')">Gerar PDF</button>`);
}
async function reabrirDocumento(id){const d=find('documentos',id);if(!d)return;await exportPdf(aplicarAssinaturasDocumento(d.html,d),`${fileSafe(d.tipo)}_${id}.pdf`)}
function pdfHead(){const c=CFG.company;return `<div class="pdf-head"><img src="./assets/logo-safety-equipamentos.jpeg"><div class="company"><b>${esc(c.name)}</b><br>CNPJ ${esc(c.cnpj)}<br>${esc(c.phone)}<br>${esc(c.email)}<br>${esc(c.address)}</div></div>`}
function pdfFooter(){return `<div class="pdf-footer">Safety Equipamentos · Documento gerado pelo Safety - Controle de Equipamentos em ${dateTimeBR(nowISO())}</div>`}
function docLocacao(l,tipo){const c=find('clientes',l.clienteId);return `<div class="pdf-doc">${pdfHead()}<h1 class="pdf-title">${esc(tipo.toUpperCase())}</h1><div class="pdf-meta"><b>Cliente:</b> ${esc(c?.nomeRazao||'')} · <b>CPF/CNPJ:</b> ${esc(c?.cpfCnpj||'')}<br><b>Responsável:</b> ${esc(l.responsavel||c?.responsavel||'—')}<br><b>Endereço de instalação:</b> ${esc(formatAddress(l.enderecoInstalacao))}<br><b>Período:</b> ${dateBR(l.inicio)} a ${dateBR(l.termino)}</div><div class="pdf-section"><h3>Equipamentos</h3><table class="pdf-table"><thead><tr><th>Equipamento</th><th>Nº de série</th><th>Valor mensal</th></tr></thead><tbody>${(l.itens||[]).map(i=>`<tr><td>${esc(i.descricaoSnapshot||equipName(i.equipamentoId))}</td><td>${esc(i.serialSnapshot||'')}</td><td>${brl(i.valorMensal)}</td></tr>`).join('')}</tbody></table></div><div class="pdf-section"><p>Os equipamentos são entregues em condições de funcionamento conforme testes e registros técnicos aplicáveis. Alterações de endereço, substituições, prorrogações e devoluções devem ser registradas junto à Safety Equipamentos.</p></div>${pdfFooter()}</div>`}
function docOrcamento(a){return `<div class="pdf-doc">${pdfHead()}<h1 class="pdf-title">ORÇAMENTO</h1><div class="pdf-meta"><b>Cliente:</b> ${esc(clientName(a.clienteId))}<br><b>Equipamento:</b> ${esc([a.equipamentoTipo,a.marca,a.modelo].filter(Boolean).join(' '))}<br><b>Nº de série:</b> ${esc(a.serial)}</div><div class="pdf-section"><h3>Diagnóstico / serviços propostos</h3><p>${esc(a.diagnostico||a.defeitoRelatado||'')}</p><p>${esc(a.servicos||'')}</p></div><div class="pdf-section"><h3>Valor total</h3><p style="font-size:18px"><b>${brl(a.orcamentoValor||0)}</b></p></div>${pdfFooter()}</div>`}
function docRelatorio(a){const tests=active('testes').filter(t=>t.assistenciaId===a.id).sort((x,y)=>(y.data||'').localeCompare(x.data||'')),t=tests[0];return `<div class="pdf-doc">${pdfHead()}<h1 class="pdf-title">RELATÓRIO DE MANUTENÇÃO</h1><div class="pdf-meta"><b>Cliente:</b> ${esc(clientName(a.clienteId))}<br><b>Equipamento:</b> ${esc([a.equipamentoTipo,a.marca,a.modelo].filter(Boolean).join(' '))}<br><b>Nº de série:</b> ${esc(a.serial)}<br><b>Data:</b> ${dateBR(t?.data||todayISO())}</div><div class="pdf-section"><h3>Serviços executados</h3><p>${esc(a.servicos||a.diagnostico||'')}</p></div>${t?`<div class="pdf-section"><h3>Teste técnico</h3><table class="pdf-table"><tbody>${(t.itens||[]).map(i=>`<tr><th>${esc(i.item)}</th><td>${esc(i.valor)}</td></tr>`).join('')}<tr><th>Resultado</th><td>${esc(t.resultado)}</td></tr></tbody></table></div>`:''}${pdfFooter()}</div>`}
function docRecibo(a){return `<div class="pdf-doc">${pdfHead()}<h1 class="pdf-title">RECIBO</h1><div class="pdf-section"><p>Recebemos de <b>${esc(clientName(a.clienteId))}</b> a importância de <b>${brl(a.orcamentoValor||0)}</b>, referente ao serviço realizado no equipamento ${esc([a.equipamentoTipo,a.marca,a.modelo].filter(Boolean).join(' '))}, nº de série <b>${esc(a.serial)}</b>.</p></div>${pdfFooter()}</div>`}
function docMovimento(m){const title=m.tipo==='Substituição'?'SUBSTITUIÇÃO DE EQUIPAMENTO':'TERMO DE EMPRÉSTIMO';return `<div class="pdf-doc">${pdfHead()}<h1 class="pdf-title">${title}</h1><div class="pdf-meta"><b>Cliente:</b> ${esc(clientName(m.clienteId))}<br><b>Data:</b> ${dateTimeBR(m.em)}</div><div class="pdf-section"><p>${esc(m.descricao||'')}</p></div>${pdfFooter()}</div>`}
async function exportPdf(html,name){
  const area=$('printArea');area.innerHTML=html;area.style.display='block';const el=area.firstElementChild;
  try{
    if(window.html2pdf){const blob=await html2pdf().set({margin:8,filename:name,image:{type:'jpeg',quality:.96},html2canvas:{scale:1.7,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}}).from(el).outputPdf('blob');const file=new File([blob],name,{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){if(confirm('PDF gerado. Deseja compartilhar agora pelo WhatsApp, e-mail ou outro aplicativo?'))await navigator.share({files:[file],title:name,text:'Documento Safety Equipamentos'});else downloadBlob(blob,name)}else downloadBlob(blob,name)}else window.print();
  }catch(e){console.error(e);window.print()}finally{area.innerHTML='';area.style.display='none'}
}
function downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000)}

