function viewUsuarios(){const rows=active('usuarios').sort((a,b)=>(a.nome||'').localeCompare(b.nome||''));return `<div class="card"><div class="row" style="align-items:center"><div><h2>Usuários</h2><p class="hint">Todos os usuários habilitados possuem acesso integral ao aplicativo. A administração de usuários exige usuário administrador.</p></div><div class="inline-actions" style="justify-content:flex-end">${currentUser.admin?`<button class="btn" onclick="novoUsuario()">+ Novo usuário</button>`:''}</div></div>${rows.length?`<table><thead><tr><th>Nome</th><th>E-mail</th><th>Ativo</th><th>Administrador</th><th>Ações</th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${esc(u.nome)}</b></td><td>${esc(u.email||'')}</td><td>${u.ativo!==false?tag('Sim','ok'):tag('Não','danger')}</td><td>${u.admin?tag('Sim','warn'):tag('Não','info')}</td><td>${currentUser.admin&&u.id!==currentUser.uid?`<button class="btn small ghost" onclick="toggleUsuario('${u.id}',${u.ativo!==false?'false':'true'})">${u.ativo!==false?'Desativar':'Ativar'}</button>`:'—'}</td></tr>`).join('')}</tbody></table>`:empty('Nenhum usuário cadastrado.')}</div>`}
function novoUsuario(){if(!currentUser.admin)return;abrirModal('Novo usuário',`<div class="grid2"><div><label>Nome *</label><input id="nuNome"></div><div><label>E-mail *</label><input id="nuEmail" type="email"></div><div><label>Senha provisória *</label><input id="nuSenha" type="password" minlength="6"></div><div><label>Administrador</label><select id="nuAdmin"><option value="false">Não</option><option value="true">Sim</option></select></div></div><p class="hint">O usuário poderá trocar a senha pelo fluxo “Esqueci minha senha”.</p>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarNovoUsuario()">Criar usuário</button>`)}
async function salvarNovoUsuario(){const nome=$('nuNome').value.trim(),email=$('nuEmail').value.trim(),senha=$('nuSenha').value;if(!nome||!email||senha.length<6)return alert('Preencha os dados e use senha com no mínimo 6 caracteres.');try{const secondary=firebase.initializeApp(CFG.firebase,'ce-secondary-'+Date.now()),cred=await secondary.auth().createUserWithEmailAndPassword(email,senha),uid=cred.user.uid;await db.collection(COLS.usuarios).doc(uid).set({nome,email,ativo:true,admin:$('nuAdmin').value==='true',criadoEm:nowISO(),criadoPor:currentUser.uid});await secondary.auth().signOut();await secondary.delete();await audit('criar','Usuários',uid,`Usuário ${nome} criado.`);fecharModal();await refresh('Usuário criado.')}catch(e){alert('Não foi possível criar o usuário: '+e.message)}}
async function toggleUsuario(uid,ativo){await setDoc(COLS.usuarios,uid,{ativo});await audit('status','Usuários',uid,`Usuário ${ativo?'ativado':'desativado'}.`);await refresh('Usuário atualizado.')}

