function viewConfiguracoes(){const cfg=configDoc(),cats=active('categorias'),fabs=active('fabricantes');return `<div class="card"><h2>Configurações</h2><div class="grid2"><div><h3>Implantação da base</h3><p class="hint">Enquanto a base estiver em implantação, o Dashboard identifica os indicadores como parciais.</p><label>Status da base</label><select id="cfgBase"><option value="implantacao" ${cfg.baseStatus==='implantacao'?'selected':''}>Em implantação</option><option value="operacao" ${cfg.baseStatus==='operacao'?'selected':''}>Operação regular</option></select><div class="grid2"><div><label>Alerta de contrato (dias)</label><input id="cfgContrato" type="number" value="${cfg.diasAlertaContrato||30}"></div><div><label>Alerta preventiva (dias)</label><input id="cfgPrev" type="number" value="${cfg.diasAlertaPreventiva||15}"></div></div><button class="btn" onclick="salvarConfigGeral()">Salvar configurações</button></div><div><h3>Fabricantes / marcas</h3><div class="inline-actions"><input id="fabNome" placeholder="Novo fabricante" style="max-width:260px"><button class="btn small" onclick="addFabricante()">Adicionar</button></div><div class="chip-list" style="margin-top:10px">${fabs.map(f=>`<span class="chip">${esc(f.nome)}</span>`).join('')||'<span class="hint">Nenhum fabricante cadastrado.</span>'}</div></div></div></div>
  <div class="card"><div class="row" style="align-items:center"><div><h2>Categorias e modelos técnicos</h2><p class="hint">Cada categoria define seus próprios parâmetros/checklists. Isso permite atender autoclaves, compressores, máquinas de solda e futuros equipamentos sem alterar a estrutura do aplicativo.</p></div><div class="inline-actions" style="justify-content:flex-end"><button class="btn" onclick="editarCategoria()">+ Nova categoria</button></div></div>${cats.length?`<table><thead><tr><th>Categoria</th><th>Itens de teste</th><th>Checklist saída</th><th>Checklist retorno</th><th>Ações</th></tr></thead><tbody>${cats.map(c=>`<tr><td><b>${esc(c.nome)}</b></td><td>${(c.itensTeste||[]).length}</td><td>${(c.checklistSaida||[]).length}</td><td>${(c.checklistRetorno||[]).length}</td><td><button class="btn small ghost" onclick="editarCategoria('${c.id}')">Editar</button></td></tr>`).join('')}</tbody></table>`:empty('Cadastre as categorias utilizadas pela Safety.')}</div>`}
async function salvarConfigGeral(){await db.collection(COLS.configuracoes).doc('geral').set({baseStatus:$('cfgBase').value,diasAlertaContrato:Number($('cfgContrato').value||30),diasAlertaPreventiva:Number($('cfgPrev').value||15),alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});await audit('editar','Configurações','geral','Configurações gerais atualizadas.');await refresh('Configurações salvas.')}
async function addFabricante(){const nome=$('fabNome').value.trim();if(!nome)return;await addDoc(COLS.fabricantes,{nome,ativo:true});await refresh('Fabricante adicionado.')}
function editarCategoria(id=''){const c=id?find('categorias',id):{};abrirModal(id?'Editar categoria':'Nova categoria',`<label>Nome da categoria *</label><input id="catNome" value="${esc(c.nome||'')}"><label>Itens / parâmetros do teste técnico</label><textarea id="catTeste" placeholder="Um item por linha">${esc((c.itensTeste||[]).join('\n'))}</textarea><label>Checklist de saída</label><textarea id="catSaida" placeholder="Um item por linha">${esc((c.checklistSaida||[]).join('\n'))}</textarea><label>Checklist de retorno</label><textarea id="catRetorno" placeholder="Um item por linha">${esc((c.checklistRetorno||[]).join('\n'))}</textarea><div class="grid2"><div><label>Periodicidade preventiva (dias, opcional)</label><input id="catPrev" type="number" value="${esc(c.preventivaDias||'')}"></div><div><label>Ativa</label><select id="catAtiva"><option value="true" ${c.ativo!==false?'selected':''}>Sim</option><option value="false" ${c.ativo===false?'selected':''}>Não</option></select></div></div>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarCategoria('${id}')">Salvar</button>`)}
async function salvarCategoria(id){const nome=$('catNome').value.trim();if(!nome)return alert('Informe o nome.');const obj={nome,itensTeste:parseList($('catTeste').value),checklistSaida:parseList($('catSaida').value),checklistRetorno:parseList($('catRetorno').value),preventivaDias:Number($('catPrev').value||0),ativo:$('catAtiva').value==='true'};if(id)await setDoc(COLS.categorias,id,obj);else await addDoc(COLS.categorias,obj);await audit(id?'editar':'criar','Configurações',id||nome,`Categoria ${nome} salva.`);fecharModal();await refresh('Categoria salva.')}

