function viewAuditoria(){const rows=active('auditoria').sort((a,b)=>(b.em||'').localeCompare(a.em||'')).slice(0,300);return `<div class="card"><h2>Auditoria</h2><p class="hint">Registro das principais ações realizadas no sistema. Assinaturas eletrônicas vetoriais e metadados permanecem vinculados aos respectivos registros; PDFs e fotos não são armazenados.</p>${rows.length?`<table><thead><tr><th>Data/hora</th><th>Usuário</th><th>Módulo</th><th>Ação</th><th>Resumo</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${dateTimeBR(a.em)}</td><td>${esc(a.nome||a.uid||'')}</td><td>${esc(a.module||'')}</td><td>${esc(a.action||'')}</td><td>${esc(a.summary||'')}</td></tr>`).join('')}</tbody></table>`:empty('Nenhum evento de auditoria.')}</div>`}

