// CSV / implantação
// ============================================================
function csvEscape(v){v=String(v??'');return /[;"\n]/.test(v)?`"${v.replace(/"/g,'""')}"`:v}
function downloadModeloCSV(tipo){let rows=[];if(tipo==='clientes')rows=[['tipoPessoa','nomeRazao','cpfCnpj','responsavel','cpfResponsavel','segmento','telefone','telefoneReferencia','email','origem','logradouro','numero','complemento','bairro','cidade','uf','cep'],['PJ','Cliente Exemplo','00.000.000/0001-00','Responsável Exemplo','','Odontologia','21999999999','','cliente@exemplo.com','OLX','Rua Exemplo','100','Sala 1','Centro','Rio de Janeiro','RJ','20000-000']];if(tipo==='equipamentos')rows=[['categoria','tipo','marca','modelo','serial','tensao','situacao','localAtual'],['Autoclave','Autoclave','Marca','Modelo','SERIE123','220V','Disponível','Safety']];if(tipo==='locacoes')rows=[['cpfCnpjCliente','serialEquipamento','inicio','termino','valorMensal','status','responsavel'],['00.000.000/0001-00','SERIE123',todayISO(),'2027-10-09','200','Ativa','Responsável Exemplo']];const text='\ufeff'+rows.map(r=>r.map(csvEscape).join(';')).join('\n');downloadBlob(new Blob([text],{type:'text/csv;charset=utf-8'}),`modelo_${tipo}.csv`)}
function parseCSV(text){const delim=(text.split('\n')[0].match(/;/g)||[]).length>=(text.split('\n')[0].match(/,/g)||[]).length?';':',';const rows=[];let row=[],cur='',q=false;for(let i=0;i<text.length;i++){const ch=text[i],nx=text[i+1];if(ch==='"'){if(q&&nx==='"'){cur+='"';i++}else q=!q}else if(ch===delim&&!q){row.push(cur);cur=''}else if((ch==='\n'||ch==='\r')&&!q){if(ch==='\r'&&nx==='\n')i++;row.push(cur);if(row.some(x=>x.trim()))rows.push(row);row=[];cur=''}else cur+=ch}row.push(cur);if(row.some(x=>x.trim()))rows.push(row);const head=rows.shift().map(x=>x.trim().replace(/^\ufeff/,''));return rows.map(r=>Object.fromEntries(head.map((h,i)=>[h,(r[i]||'').trim()]))) }
async function importarCSV(ev,tipo){const file=ev.target.files[0];if(!file)return;const rows=parseCSV(await file.text());if(!rows.length)return alert('Arquivo sem registros.');if(!confirm(`Importar ${rows.length} registro(s) para ${tipo}?`))return;let ok=0,err=[];for(const [idx,r] of rows.entries()){try{if(tipo==='clientes'){if(!r.nomeRazao||!r.cpfCnpj)throw new Error('nome/documento ausente');await addDoc(COLS.clientes,{tipoPessoa:r.tipoPessoa||'PF',nomeRazao:r.nomeRazao,cpfCnpj:r.cpfCnpj,responsavel:r.responsavel||'',cpfResponsavel:r.cpfResponsavel||'',segmento:r.segmento||'',telefone:r.telefone||'',telefoneReferencia:r.telefoneReferencia||'',email:r.email||'',origem:r.origem||'Importação',enderecoCadastral:{logradouro:r.logradouro||'',numero:r.numero||'',complemento:r.complemento||'',bairro:r.bairro||'',cidade:r.cidade||'',uf:r.uf||'',cep:r.cep||''},enderecosInstalacao:[],historicoCadastral:[],ativo:true})}else if(tipo==='equipamentos'){if(!r.serial||!r.tipo)throw new Error('tipo/série ausente');let cat=data.categorias.find(c=>normalize(c.nome)===normalize(r.categoria));const obj={categoriaId:cat?.id||'',categoriaNome:r.categoria||'',tipo:r.tipo,marca:r.marca||'',modelo:r.modelo||'',serial:r.serial,tensao:r.tensao||'',situacao:r.situacao||'Disponível',localAtual:r.localAtual||'Safety',ativo:true};await addDoc(COLS.equipamentos,obj)}else if(tipo==='locacoes'){const cli=data.clientes.find(c=>normalize(c.cpfCnpj)===normalize(r.cpfCnpjCliente)),eq=data.equipamentos.find(e=>normalize(e.serial)===normalize(r.serialEquipamento));if(!cli||!eq)throw new Error('cliente ou série não encontrado');await addDoc(COLS.locacoes,{clienteId:cli.id,responsavel:r.responsavel||cli.responsavel||'',inicio:r.inicio,termino:r.termino,tipoDocumento:daysBetween(r.inicio,r.termino)<=30?'30dias':'contrato',status:r.status||'Ativa',enderecoInstalacao:(cli.enderecosInstalacao||[])[0]||cli.enderecoCadastral||{},itens:[{equipamentoId:eq.id,serialSnapshot:eq.serial,descricaoSnapshot:equipName(eq.id),valorMensal:num(r.valorMensal)}],prorrogacoes:[],ativo:true});await setDoc(COLS.equipamentos,eq.id,{situacao:(r.status||'Ativa')==='Ativa'?'Alugado':'Reservado'})}ok++}catch(e){err.push(`Linha ${idx+2}: ${e.message}`)}}await audit('importar','Implantação',tipo,`${ok} registros importados; ${err.length} com erro.`);await refresh(`${ok} registro(s) importado(s).${err.length?' '+err.length+' erro(s).':''}`);if(err.length)alert(err.slice(0,15).join('\n'))}

